//! Differential test: the Winterfell STARK vs an exact integer reference vs the TypeScript float
//! risk model on a seeded corpus of >= 2000 random + boundary witnesses
//! (`fixtures/differential_corpus.json`, generated by `tests/gen_differential_corpus.mjs`).
//!
//! Allow/deny of the STARK is *behavioural*: a witness is "allowed" iff `prove_release` returns a
//! proof AND the real verifier accepts it for the public inputs. A deny witness must therefore
//! never produce a verifying proof. Run: `cargo test --release --test differential -- --nocapture`.

use stark_pca::{compute_witness_commitment, prove_release, risk_raw, verify_release, PolicyParams, Witness};
use winterfell::math::StarkField;

#[derive(serde::Deserialize)]
struct Corpus {
    policy: Pol,
    in_domain_cases: usize,
    cases: Vec<Case>,
}
#[derive(serde::Deserialize)]
struct Pol {
    weights_scaled: [u64; 6],
    theta1_scaled: u64,
    kappa: u64,
    bmax_scaled: u64,
}
#[derive(serde::Deserialize, Clone)]
struct Case {
    class: String,
    in_domain: bool,
    inputs_scaled: [String; 6],
    budget_scaled: String,
    predicate_match: bool,
    caveats_ok: bool,
    exact_allow: bool,
    exact_rraw: String,
    ts_allow: bool,
}

fn load() -> Corpus {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/differential_corpus.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("corpus")).expect("parse corpus")
}

fn witness(c: &Case) -> Witness {
    Witness {
        inputs: core::array::from_fn(|i| c.inputs_scaled[i].parse().unwrap()),
        budget_scaled: c.budget_scaled.parse().unwrap(),
        predicate_match: c.predicate_match,
        caveats_ok: c.caveats_ok,
    }
}

/// STARK decision: a verifying proof exists for this witness under the default policy.
fn stark_allows(w: &Witness) -> bool {
    let mut policy = PolicyParams::default_policy();
    let wc = compute_witness_commitment(w);
    policy.witness_commitment = core::array::from_fn(|m| wc[m].as_int().to_string());
    let (w2, p2) = (w.clone(), policy.clone());
    match std::panic::catch_unwind(move || prove_release(&w2, &p2)) {
        Ok(Ok(proof)) => verify_release(proof, &policy).is_ok(),
        _ => false,
    }
}

#[test]
fn stark_agrees_with_exact_reference_on_the_corpus() {
    let corpus = load();
    assert!(corpus.in_domain_cases >= 2000, "corpus must hold >= 2000 in-domain witnesses");
    let dp = PolicyParams::default_policy();
    assert_eq!(dp.weights, corpus.policy.weights_scaled);
    assert_eq!((dp.theta1_scaled, dp.kappa, dp.bmax_scaled), (corpus.policy.theta1_scaled, corpus.policy.kappa, corpus.policy.bmax_scaled));
    std::panic::set_hook(Box::new(|_| {}));

    // run the cases on 4 worker threads
    let cases: Vec<Case> = corpus.cases.clone();
    let results: Vec<(bool, bool)> = std::thread::scope(|s| {
        let chunk = cases.len().div_ceil(4);
        let hs: Vec<_> = cases
            .chunks(chunk)
            .map(|ch| {
                s.spawn(move || {
                    ch.iter()
                        .map(|c| {
                            let w = witness(c);
                            // the integer image of the risk functional must equal the BigInt reference
                            if c.in_domain {
                                assert_eq!(risk_raw(&w.inputs, &PolicyParams::default_policy().weights).to_string(), c.exact_rraw, "risk_raw");
                            }
                            (stark_allows(&w), c.in_domain)
                        })
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        hs.into_iter().flat_map(|h| h.join().unwrap()).collect()
    });
    let _ = std::panic::take_hook();

    let (mut n_in, mut n_allow, mut n_deny, mut ts_dis_lenient, mut ts_dis_strict) = (0, 0, 0, 0, 0);
    let mut ood_denied = 0;
    for (c, (stark, in_domain)) in corpus.cases.iter().zip(results) {
        if in_domain {
            n_in += 1;
            assert_eq!(stark, c.exact_allow, "STARK vs exact reference disagree on {} {:?} B={} pm={} co={}", c.class, c.inputs_scaled, c.budget_scaled, c.predicate_match, c.caveats_ok);
            if c.exact_allow { n_allow += 1 } else { n_deny += 1 }
            if c.ts_allow != c.exact_allow {
                // The float TS model must never be MORE permissive than the exact relation, and may
                // differ only at an exact equality (r_raw == theta1*S^2 or B*S == kappa*r_raw).
                if c.ts_allow { ts_dis_lenient += 1 } else { ts_dis_strict += 1 }
                let raw: u128 = c.exact_rraw.parse().unwrap();
                let b: u128 = c.budget_scaled.parse().unwrap();
                let at_theta = raw == corpus.policy.theta1_scaled as u128 * 1_000_000;
                let at_budget = b * 1_000_000 == corpus.policy.kappa as u128 * raw;
                assert!(at_theta || at_budget, "TS float disagrees away from an exact boundary: {} raw={raw} B={b}", c.class);
            }
        } else {
            // outside the quantization domain the STARK must always refuse
            assert!(!stark, "out-of-domain witness produced a verifying proof: {} {:?} B={}", c.class, c.inputs_scaled, c.budget_scaled);
            ood_denied += 1;
        }
    }
    assert_eq!(ts_dis_lenient, 0, "TS float model was more permissive than the exact relation");
    assert!(n_in >= 2000 && n_allow > 400 && n_deny > 400, "corpus not balanced: in={n_in} allow={n_allow} deny={n_deny}");
    eprintln!(
        "differential: in-domain={n_in} (allow {n_allow}, deny {n_deny}) all agree with the exact reference; out-of-domain denied={ood_denied}; \
         TS-float stricter-than-exact at an exact boundary: {ts_dis_strict}; TS-float more permissive: {ts_dis_lenient}"
    );
}
